class tlc_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(tlc_scoreboard)

  uvm_analysis_imp #(tlc_seq_item, tlc_scoreboard) ap;

  // Reference model state
  typedef enum logic [2:0] {S0 = 0, S1 = 1, S2 = 2, S3 = 3, SR = 4} state_e;
  state_e ref_state;
  logic [1:0] exp_light_NS, exp_light_EW;

  // Counters
  int unsigned match_count;
  int unsigned mismatch_count;
  int unsigned total_count;
  bit prev_reset;       // Track previous cycle's reset for state update
  bit first_sample;     // Flag for first sample

  function new(string name = "tlc_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    ref_state = SR;
    match_count = 0;
    mismatch_count = 0;
    total_count = 0;
    prev_reset = 1;
    first_sample = 1;
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap = new("ap", this);
  endfunction

  // Reference model: compute expected outputs based on current ref_state
  function void compute_expected();
    case (ref_state)
      S0: begin exp_light_NS = 2'b10; exp_light_EW = 2'b00; end
      S1: begin exp_light_NS = 2'b01; exp_light_EW = 2'b00; end
      S2: begin exp_light_NS = 2'b00; exp_light_EW = 2'b10; end
      S3: begin exp_light_NS = 2'b00; exp_light_EW = 2'b01; end
      SR: begin exp_light_NS = 2'b00; exp_light_EW = 2'b00; end
      default: begin exp_light_NS = 2'b00; exp_light_EW = 2'b00; end
    endcase
  endfunction

  // Advance reference model state
  function void advance_state();
    case (ref_state)
      S0: ref_state = S1;
      S1: ref_state = S2;
      S2: ref_state = S3;
      S3: ref_state = S0;
      SR: ref_state = S0;
      default: ref_state = S0;
    endcase
  endfunction

  virtual function void write(tlc_seq_item item);
    total_count++;

    // If reset was asserted in the previous cycle (or is currently asserted),
    // the state should be SR
    if (item.reset_val) begin
      ref_state = SR;
    end

    // Compute expected outputs for current state
    compute_expected();

    // Compare
    if (item.light_NS === exp_light_NS && item.light_EW === exp_light_EW) begin
      match_count++;
      `uvm_info("SCB", $sformatf("MATCH [%0d]: state=%s NS=%02b(exp=%02b) EW=%02b(exp=%02b) reset=%0b",
                total_count, ref_state.name(), item.light_NS, exp_light_NS,
                item.light_EW, exp_light_EW, item.reset_val), UVM_HIGH)
    end else begin
      mismatch_count++;
      `uvm_error("SCB", $sformatf("MISMATCH [%0d]: state=%s NS=%02b(exp=%02b) EW=%02b(exp=%02b) reset=%0b",
                 total_count, ref_state.name(), item.light_NS, exp_light_NS,
                 item.light_EW, exp_light_EW, item.reset_val))
    end

    // Advance reference state for next cycle (only if not in reset)
    if (!item.reset_val) begin
      advance_state();
    end

    prev_reset = item.reset_val;
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SCB", $sformatf("====== Scoreboard Summary ======"), UVM_LOW)
    `uvm_info("SCB", $sformatf("Total transactions: %0d", total_count), UVM_LOW)
    `uvm_info("SCB", $sformatf("Matches:            %0d", match_count), UVM_LOW)
    `uvm_info("SCB", $sformatf("Mismatches:         %0d", mismatch_count), UVM_LOW)
    if (mismatch_count > 0)
      `uvm_error("SCB", "TEST FAILED: Mismatches detected")
    else
      `uvm_info("SCB", "TEST PASSED: All transactions matched", UVM_LOW)
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

class tlc_coverage extends uvm_subscriber #(tlc_seq_item);
  `uvm_component_utils(tlc_coverage)

  // Local copies for sampling
  logic [1:0] light_NS;
  logic [1:0] light_EW;
  bit         reset_val;

  // Previous cycle values for transition coverage
  logic [1:0] prev_light_NS;
  logic [1:0] prev_light_EW;
  bit         prev_valid;

  covergroup cg_traffic_lights;
    option.per_instance = 1;

    // Individual light values
    cp_light_NS: coverpoint light_NS {
      bins red    = {2'b00};
      bins yellow = {2'b01};
      bins green  = {2'b10};
      bins illegal = {2'b11};
    }

    cp_light_EW: coverpoint light_EW {
      bins red    = {2'b00};
      bins yellow = {2'b01};
      bins green  = {2'b10};
      bins illegal = {2'b11};
    }

    // Reset coverpoint
    cp_reset: coverpoint reset_val {
      bins active   = {1};
      bins inactive = {0};
    }

    // Cross coverage: light combinations
    cx_lights: cross cp_light_NS, cp_light_EW {
      // Expected legal combinations
      bins s0_state = binsof(cp_light_NS.green)  && binsof(cp_light_EW.red);
      bins s1_state = binsof(cp_light_NS.yellow) && binsof(cp_light_EW.red);
      bins s2_state = binsof(cp_light_NS.red)    && binsof(cp_light_EW.green);
      bins s3_state = binsof(cp_light_NS.red)    && binsof(cp_light_EW.yellow);
      bins sr_state = binsof(cp_light_NS.red)    && binsof(cp_light_EW.red);
      // All others are illegal
      //illegal_bins bad_combo = default;
    }

    // Cross with reset
    cx_reset_lights: cross cp_reset, cp_light_NS, cp_light_EW {
      bins reset_both_red = binsof(cp_reset.active) &&
                            binsof(cp_light_NS.red) && binsof(cp_light_EW.red);
    }
  endgroup

  // Transition coverage for state sequences
  covergroup cg_transitions;
    option.per_instance = 1;

    // NS light transitions
    cp_ns_trans: coverpoint light_NS {
      bins green_to_yellow  = (2'b10 => 2'b01);
      bins yellow_to_red    = (2'b01 => 2'b00);
      bins red_to_red       = (2'b00 => 2'b00);
      bins red_to_green     = (2'b00 => 2'b10);
    }

    // EW light transitions
    cp_ew_trans: coverpoint light_EW {
      bins red_to_red       = (2'b00 => 2'b00);
      bins red_to_green     = (2'b00 => 2'b10);
      bins green_to_yellow  = (2'b10 => 2'b01);
      bins yellow_to_red    = (2'b01 => 2'b00);
    }
  endgroup

  // State output combination coverage
  covergroup cg_state_outputs;
    option.per_instance = 1;

    // Combined output as a 4-bit value {NS, EW}
    cp_combined: coverpoint {light_NS, light_EW} {
      bins s0 = {4'b1000};  // NS=GREEN, EW=RED
      bins s1 = {4'b0100};  // NS=YELLOW, EW=RED
      bins s2 = {4'b0010};  // NS=RED, EW=GREEN
      bins s3 = {4'b0001};  // NS=RED, EW=YELLOW
      bins sr = {4'b0000};  // Both RED
    }

    // Full cycle transition
    cp_full_cycle: coverpoint {light_NS, light_EW} {
      bins full_cycle = (4'b1000 => 4'b0100 => 4'b0010 => 4'b0001 => 4'b1000);
    }
  endgroup

  function new(string name = "tlc_coverage", uvm_component parent = null);
    super.new(name, parent);
    cg_traffic_lights = new();
    cg_transitions    = new();
    cg_state_outputs  = new();
    prev_valid = 0;
  endfunction

  virtual function void write(tlc_seq_item t);
    light_NS  = t.light_NS;
    light_EW  = t.light_EW;
    reset_val = t.reset_val;

    cg_traffic_lights.sample();
    cg_state_outputs.sample();

    if (prev_valid) begin
      cg_transitions.sample();
    end

    prev_light_NS = light_NS;
    prev_light_EW = light_EW;
    prev_valid = 1;
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("COV", $sformatf("Traffic Lights Coverage: %.2f%%",
              cg_traffic_lights.get_coverage()), UVM_LOW)
    `uvm_info("COV", $sformatf("Transitions Coverage:    %.2f%%",
              cg_transitions.get_coverage()), UVM_LOW)
    `uvm_info("COV", $sformatf("State Outputs Coverage:  %.2f%%",
              cg_state_outputs.get_coverage()), UVM_LOW)
  endfunction
endclass

