  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = tlc_env::type_id::create("env", this);
  endfunction

  virtual task run_phase(uvm_phase phase);
    tlc_random_seq rand_seq;
    phase.raise_objection(this);

    rand_seq = tlc_random_seq::type_id::create("rand_seq");
    rand_seq.start(env.agent.sqr);

    #100;
    phase.drop_objection(this);
  endtask
endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════


module tb_top;
  
  // Clock generation
  logic clk;
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100 MHz clock, 10ns period
  end

  // Instantiate the interface (using the existing fsm_if from design file)
  fsm_if intf(.clk(clk));

  // Instantiate the DUT
  traffic_light_controller dut (
    .clk      (clk),
    .reset    (intf.reset),
    .light_NS (intf.light_NS),
    .light_EW (intf.light_EW)
  );

  // Connect DUT outputs back to interface for monitoring
  // light_NS and light_EW are driven by DUT, interface monitors them
  // Since the DUT drives light_NS and light_EW, we need to connect them
  // The interface's light_NS/light_EW are wires connected to DUT outputs
  // This is handled by the port connections above

  // Store virtual interface in config_db
  initial begin
    uvm_config_db#(virtual fsm_if)::set(null, "*", "vif", intf);
  end

  // Start UVM test
  initial begin
    run_test();
  end

  // Timeout watchdog
  initial begin
    #100_000;
    `uvm_fatal("TIMEOUT", "Simulation timeout reached")
  end

  // Optional: dump waveforms
  initial begin
    $dumpfile("tlc_waves.vcd");
    $dumpvars(0, tb_top);
  end
endmodule

